const guard=fn=>async(...args)=>{try{await fn(...args);}catch(e){toast(e.message||String(e));}};
function modal(title,body){$('modalTitle').textContent=title;$('modalBody').innerHTML=body;if(!$('modal').open)$('modal').showModal();}
function closeModal(){if(preparedCancel){preparedCancel();return;}if(busy)return;$('modal').close();selected=null;if(staged){staged=null;stopWorker();}}
function qty(v){const s=en(v).replace(/٫/g,'.').replace(/٬/g,'').trim();if(!/^\d+(?:\.\d{1,3})?$/.test(s))throw Error('تعداد باید صفر یا بیشتر، با حداکثر سه رقم اعشار باشد.');const[a,b='']=s.split('.'),n=Number(a)*1000+Number(b.padEnd(3,'0'));if(!Number.isSafeInteger(n)||n>MAX)throw Error('تعداد بیش از حد مجاز است.');return n;}
function dbOpen(){return new Promise((resolve,reject)=>{const r=indexedDB.open(DB,1);r.onupgradeneeded=()=>{const d=r.result;d.createObjectStore('meta',{keyPath:'key'});d.createObjectStore('scopes',{keyPath:'id'});d.createObjectStore('catalogs',{keyPath:'scopeId'});d.createObjectStore('raw',{keyPath:'scopeId'});const e=d.createObjectStore('entries',{keyPath:'id'});e.createIndex('scopeId','scopeId');e.createIndex('scopeProductRound',['scopeId','productId','round']);e.createIndex('pending','pending');};r.onsuccess=()=>{r.result.onversionchange=()=>r.result.close();resolve(r.result);};r.onerror=()=>reject(r.error);r.onblocked=()=>reject(Error('نسخهٔ دیگری از برنامه باز است.'));});}
function read(store,key,by){return new Promise((resolve,reject)=>{const tx=db.transaction(store),s=tx.objectStore(store),r=by?s.index(by).getAll(key):key===undefined?s.getAll():s.get(key);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
