function bulk(store,rows,done){let i=0;function chunk(){let last;for(let n=Math.min(i+200,rows.length);i<n;i++)last=store.add(rows[i]);if(i<rows.length)last.onsuccess=chunk;else done?.();}chunk();}
function stopWorker(){worker?.terminate();worker=null;workerPromise=null;if(workerURL)URL.revokeObjectURL(workerURL);workerURL=null;for(const j of workerJobs.values()){clearTimeout(j.timer);j.reject(Error('پردازش فایل متوقف شد.'));}workerJobs.clear();}
async function getWorker(){if(worker)return worker;if(workerPromise)return workerPromise;workerPromise=(async()=>{const response=await fetch('excel-worker.js');if(!response.ok)throw Error('فایل پردازشگر داخل برنامه کامل نیست.');const blob=await response.blob();workerURL=URL.createObjectURL(new Blob([blob],{type:'text/javascript'}));worker=new Worker(workerURL);worker.onmessage=({data:m})=>{const j=workerJobs.get(m.id);if(!j)return;clearTimeout(j.timer);workerJobs.delete(m.id);m.error?j.reject(Error(m.error)):j.resolve(m.result);};worker.onerror=()=>stopWorker();return worker;})();try{return await workerPromise;}catch(e){stopWorker();throw e;}}
async function excelTask(type,data,transfer=[]){const w=await getWorker();return new Promise((resolve,reject)=>{const id=++workerJob,timer=setTimeout(()=>stopWorker(),180000);workerJobs.set(id,{resolve,reject,timer});w.postMessage({id,type,data},transfer);});}
function to64(buf){const a=new Uint8Array(buf);let s='';for(let i=0;i<a.length;i+=32768)s+=String.fromCharCode(...a.subarray(i,i+32768));return btoa(s);}
