 $('homeContent').innerHTML=`${company?'<div class="breadcrumb"><button class="plain" data-home-companies>شرکت‌ها</button><span>/ '+esc(company.name)+'</span></div>':''}<section class="dashboard-hero"><div class="hero-content"><span class="hero-eyebrow">${uiIcon('check')} همراهِ شمارش شما</span><h1>${company?esc(company.name):'همهٔ انبارها، یک‌جا.'}</h1><p>${company?'انبار موردنظر را انتخاب کنید و شمارش را ادامه دهید.':'شرکت را انتخاب کنید؛ سپس وارد انبار موردنظر شوید.'}</p>${inventoryCues}</div><div class="hero-ornament" aria-hidden="true"><span></span><span></span></div></section>${company?referencePanel(company.name):''}<section class="selection-block"><div class="topline"><div><p class="eyebrow">${company?'مرحلهٔ ۲ از ۲':'مرحلهٔ ۱ از ۲'}</p><h2>${company?'انتخاب انبار':'انتخاب شرکت'}</h2></div>${admin?'<div class="actions"><button class="primary" '+(company?'data-home-new':'data-home-add-company')+'>'+(company?'+ افزودن انبار':'مدیریت شرکت‌ها')+'</button></div>':''}</div><div class="grid">${cards}</div>${!cards?'<div class="empty">'+(company?'هنوز انباری برای این شرکت وجود ندارد.':admin?'ابتدا شرکت و سپس انبار را اضافه کنید.':'هنوز انبار آماده‌ای توسط مدیر منتشر نشده است.')+'</div>':''}</section>`;
