  const central=profile.role==='admin'&&centerReachable;if(central)await rpc('archiveCompany',{name});
  hiddenCompanies=[...new Set([...hiddenCompanies,norm(name)])];localCompanies=localCompanies.filter(c=>norm(c.name)!==norm(name));companyDirectory=companyDirectory.filter(c=>norm(c.name)!==norm(name));
